package tests; import base.BaseTest; import pages.GreenKartPage; import org.testng.Assert; import org.testng.annotations.Test; public class GreenKartSmokeTest extends BaseTest {@Test public void searchAndOpenCart(){GreenKartPage p=new GreenKartPage(driver);p.search("Brocolli");Assert.assertTrue(p.productVisible("Brocolli"),"Product search result not found");p.addFirstProduct();p.openCart();Assert.assertTrue(driver.getPageSource().contains("PROCEED TO CHECKOUT"),"Cart page did not load");}}